                Gp_EcuStpShdn_GetLastSatTimeStamp();
        }
        else
        {
            /* 测试新增 */
            MstImpl_ptst->TimeStamp_u32[GP_ECUSTPSHDN_MST_TIME_STAMP_LAST_SAT_INIT] = 0U
            /*do nothing*/
        }
    }
    else
    {
        /*do nothing*/
    }


