            {

                Gp_EcuStpShdn_CalloutMcuRunTimeTestFailedHnd();

            }
            else
            {
                /*do nothing*/
            }
        }
        else
        {
            /*do nothing*/
        }
    }
    else
    {
        /*do nothing*/
    }

}

